```javascript
import http from 'k6/http';

export const options = {
  vus: 1,
  iterations: 2,
};

export default function () {
  const baseUrl = __ENV.BASE_URL.replace(/\/+$/, '');

  // 1. POST /login
  const loginRes = http.post(
    `${baseUrl}/login`,
    JSON.stringify({ username: 'bench', password: 'bench' }),
    { headers: { 'Content-Type': 'application/json' } }
  );
  if (loginRes.status < 200 || loginRes.status >= 300) {
    throw new Error(`login failed: status=${loginRes.status} body=${loginRes.body}`);
  }
  const csrf = loginRes.json().csrf;
  if (!csrf) {
    throw new Error(`login response missing csrf: body=${loginRes.body}`);
  }

  // 2. GET /products
  const productsRes = http.get(`${baseUrl}/products`);
  if (productsRes.status < 200 || productsRes.status >= 300) {
    throw new Error(`products failed: status=${productsRes.status} body=${productsRes.body}`);
  }

  // 3. POST /cart
  const cartRes = http.post(
    `${baseUrl}/cart`,
    JSON.stringify({ product_id: 'sku-1' }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );
  if (cartRes.status < 200 || cartRes.status >= 300) {
    throw new Error(`cart failed: status=${cartRes.status} body=${cartRes.body}`);
  }

  // 4. POST /checkout
  const checkoutRes = http.post(
    `${baseUrl}/checkout`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );
  if (checkoutRes.status < 200 || checkoutRes.status >= 300) {
    throw new Error(`checkout failed: status=${checkoutRes.status} body=${checkoutRes.body}`);
  }
}
